import { css } from 'lit';

export const dataTableStyles = css`
  :host {
    display: block;
    font-family: var(--bl-font-family-base);
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    overflow: auto;
  }

  .table {
    width: 100%;
    border-collapse: collapse;
    font-size: var(--bl-font-size-sm);
  }
`;

export const tableHeaderStyles = css`
  :host {
    display: table-header-group;
  }
`;

export const tableBodyStyles = css`
  :host {
    display: table-row-group;
  }
`;

export const tableRowStyles = css`
  :host {
    display: table-row;
    transition: background-color var(--bl-transition-fast);
  }

  :host(:hover) {
    background-color: var(--bl-color-neutral-50);
  }

  :host([selected]) {
    background-color: var(--bl-color-primary-50);
  }

  :host(:not(:last-child)) {
    border-bottom: 1px solid var(--bl-color-neutral-200);
  }
`;

export const tableHeaderCellStyles = css`
  :host {
    display: table-cell;
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    text-align: left;
    font-weight: 600;
    font-size: var(--bl-font-size-xs);
    color: var(--bl-color-neutral-600);
    background-color: var(--bl-color-neutral-50);
    border-bottom: 1px solid var(--bl-color-neutral-200);
    white-space: nowrap;
    user-select: none;
  }

  .header-cell {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-xs);
  }

  :host([sortable]) .header-cell {
    cursor: pointer;
  }

  :host([sortable]) .header-cell:hover {
    color: var(--bl-color-neutral-900);
  }

  .sort-icon {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
    opacity: 0.3;
    transition: opacity var(--bl-transition-fast);
  }

  :host([aria-sort='ascending']) .sort-icon,
  :host([aria-sort='descending']) .sort-icon {
    opacity: 1;
    color: var(--bl-color-primary-600);
  }

  :host([aria-sort='descending']) .sort-icon {
    transform: rotate(180deg);
  }

  :host(:focus-visible) {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: -2px;
  }
`;

export const tableCellStyles = css`
  :host {
    display: table-cell;
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    color: var(--bl-color-neutral-700);
    vertical-align: middle;
  }

  :host(:focus-visible) {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: -2px;
  }
`;

export const tablePaginationStyles = css`
  :host {
    display: block;
    font-family: var(--bl-font-family-base);
  }

  .pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    border-top: 1px solid var(--bl-color-neutral-200);
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-600);
  }

  .info {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-sm);
  }

  .controls {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-xs);
  }

  button {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    padding: 0;
    background: none;
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    color: var(--bl-color-neutral-600);
    cursor: pointer;
    transition:
      background-color var(--bl-transition-fast),
      border-color var(--bl-transition-fast);
  }

  button:hover:not(:disabled) {
    background-color: var(--bl-color-neutral-100);
    border-color: var(--bl-color-neutral-300);
  }

  button:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  button:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: 2px;
  }

  .page-info {
    min-width: 100px;
    text-align: center;
  }
`;

import { LitElement, html } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { dataTableStyles } from './data-table.styles.js';
import { GridNavigationController } from '../controllers/grid-navigation.js';

/**
 * Data table root container with `role="grid"`.
 * Sorting is declarative — clicking a header fires `bl-sort-change`, consumer re-orders data.
 *
 * @element bl-data-table
 * @slot - `bl-table-header` and `bl-table-body` elements.
 * @fires bl-sort-change - Emitted when a sortable header is clicked.
 * @fires bl-selection-change - Emitted when row selection changes.
 * @fires bl-row-click - Emitted when a row is clicked.
 */
@customElement('bl-data-table')
export class BlDataTable extends LitElement {
  static override styles = [tokens, dataTableStyles];

  private _grid = new GridNavigationController(this, {
    rowSelector: 'bl-table-row',
    cellSelector: 'bl-table-header-cell, bl-table-cell',
  });

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'grid');
    this.addEventListener('bl-header-sort', this._handleSort as EventListener);
    this.addEventListener('bl-row-select', this._handleRowSelect as EventListener);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('bl-header-sort', this._handleSort as EventListener);
    this.removeEventListener('bl-row-select', this._handleRowSelect as EventListener);
  }

  private _handleSort = (e: CustomEvent<{ column: string; direction: string }>): void => {
    e.stopPropagation();
    this.dispatchEvent(
      new CustomEvent('bl-sort-change', {
        detail: e.detail,
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _handleRowSelect = (e: CustomEvent): void => {
    e.stopPropagation();
    const rows = Array.from(this.querySelectorAll('bl-table-row[selected]'));
    const selected = rows.map((r) => r.getAttribute('data-row-id') ?? '');
    this.dispatchEvent(
      new CustomEvent('bl-selection-change', {
        detail: { selected },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <table class="table" part="table">
        <slot></slot>
      </table>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-data-table': BlDataTable;
  }
}

